            return match result {
                KnownPatternResult::Type(pt) => {
                    if let PropType::Opaque(detail) = &pt {
                        push_known_opaque_diagnostic(
                            &mut state.diagnostics,
                            detail.reason(),
                            name.as_str(),
                            consuming_file,
